import{_ as t,o as e,c as d,ag as a}from"./chunks/framework.NIGIbcGl.js";const b=JSON.parse('{"title":"BlockSeat Bookings Guide (Admin)","description":"","frontmatter":{},"headers":[],"relativePath":"admin/blockseat-bookings/index.md","filePath":"admin/blockseat-bookings/index.md"}'),i={name:"admin/blockseat-bookings/index.md"};function n(c,o,s,r,l,k){return e(),d("div",null,[...o[0]||(o[0]=[a('<h1 id="blockseat-bookings-guide-admin" tabindex="-1">BlockSeat Bookings Guide (Admin) <a class="header-anchor" href="#blockseat-bookings-guide-admin" aria-label="Permalink to &quot;BlockSeat Bookings Guide (Admin)&quot;">​</a></h1><p>Admin management of <strong>BlockSeat</strong> (wholesale) bookings. These endpoints reuse the <a href="/ahlaan-train-docs/admin/booking-management/">Admin OTA Booking</a> service verbatim — list, detail, modify, cancel + refund, retry-ticketing, follow-ups, and status history all behave identically — scoped to <code>bookingVariant = BLOCKSEAT</code>.</p><p>BlockSeat rides the standard OTA booking flow (real supplier GROUP reservation, async ticketing). There is <strong>no manifest, no auto-confirm, and no ticket-channel / capital-price machinery</strong> — that was the custom-booking model and does not apply here.</p><p>All require admin JWT (<code>@Roles(ADMIN)</code>).</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/admin/blockseat-bookings/bookings</code></td><td>List BlockSeat bookings (filters + pagination + sort). Scoped to BLOCKSEAT.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/admin/blockseat-bookings/bookings/:id</code></td><td>Full detail (<code>_admin</code> section). Scoped to BLOCKSEAT (404 for a standard OTA row).</td></tr><tr><td><code>PATCH</code></td><td><code>/api/v1/admin/blockseat-bookings/bookings/:id/modify</code></td><td>Modify (Type 4 names, Type 9 contact, Type 40 info, Type 10 cancel segment).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/admin/blockseat-bookings/bookings/:id/cancel</code></td><td>Cancel + refund (reason required; auto-records follow-up).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/admin/blockseat-bookings/bookings/:id/retry-ticketing</code></td><td>Re-queue ticketing for a CONFIRMED / stuck booking.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/admin/blockseat-bookings/bookings/:id/tickets</code></td><td>Download tickets (ZIP).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/admin/blockseat-bookings/bookings/:id/follow-up</code></td><td>Record an admin follow-up (outreach / note).</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/admin/blockseat-bookings/bookings/:id/follow-ups</code></td><td>List the follow-up trail.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/admin/blockseat-bookings/bookings/:id/status-history</code></td><td>Lifecycle/ticketing trail (newest first).</td></tr></tbody></table><p>Payment, ticketing, expiry, and refund behaviour are shared with standard OTA bookings — see <a href="/ahlaan-train-docs/admin/booking-management/">Admin OTA Booking</a> for full field-level detail of each operation. Wholesale route reducers are configured under <a href="/ahlaan-train-docs/admin/blockseat-route-price/">BlockSeat Route Pricing</a>.</p>',6)])])}const m=t(i,[["render",n]]);export{b as __pageData,m as default};
